) AS (
  VALUES 
    (440::BIGINT, 'Es verdad que uno no aprende mucho en su curso, pero uno queda con la idea de como aprovechar lo que se logró ver, además sirve para el ponderado porque se pasa con 100, es super amable y cuenta bastantes experiencias que ha vivido como profesional.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, 'df3bd3b0517b80c6b255102777200debd8712087c90dd541dc4afd52b00d9e91'::TEXT, ARRAY[1739]::BIGINT[]),
    (440::BIGINT, 'Es súper buena gente pero mal profe. El curso está regalado y no le importa mucho la asistencia. Hay evaluaciones en grupo casi todas las semanas pero igual parece que no las revisa.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-09T00:00:00+00:00'::TIMESTAMPTZ, '94735399a93d7cc68688879cb1bfa53bf78d14c53a2a144d60f7a826df8fb830'::TEXT, ARRAY[1739]::BIGINT[]),
    (440::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-10-24T00:00:00+00:00'::TIMESTAMPTZ, 'ef231a1394b4ce7f9fa8d4ff9cf025dac971452b5c3ed76151fda79414472e42'::TEXT, ARRAY[1739]::BIGINT[]),
    (440::BIGINT, 'Demasiado buena gente, es facil de pasar, matriculen con el si quieren chillear'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2025-08-13T00:00:00+00:00'::TIMESTAMPTZ, 'c1f6e99554052d5194acefb4960052361a015e960b74199095e35012ee6570c6'::TEXT, ARRAY[1749]::BIGINT[]),
    (440::BIGINT, 'Me la pase durmiendo en clase. Es desordenado, se suponía teniamos 2 examenes y nunca los hizo, es un poco dificil de contactar. La verdad el tiene conocimiento pero, no sabe como enseñarlo. En clase la pase durmiendo o perdiendo el tiempo, se pasa si o si porque no se aprende'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'e585e11e113ce8db4aafe7e0a2f6342e4773b70d1a0e6a459bb3ed87f8b562d3'::TEXT, ARRAY[1739]::BIGINT[]),
    (440::BIGINT, 'Es muy buena persona, no hace el curso pesado, pero lo triste es que es un curso perdido por ver aplicaciones que ya nadie usa. La mayoría de cosas son en grupos de 3, es importante tener un buen grupo para los trabajos.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2025-07-04T00:00:00+00:00'::TIMESTAMPTZ, '2d26232bfc56e491f2533386c43ef3b386a9b8961fb1e9697e027d42454c8b07'::TEXT, ARRAY[1739]::BIGINT[]),
    (440::BIGINT, 'Lemaitre es excelente persona, pero pésimo profesor. Que lastima porque es un curso donde se puede aprender mucho, lastimosamente se desperdicia. Uno va a pasar, pero no va a aprender nada y hasta va a ser tedioso porque no se entiende bien las instrucciones.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, '4153b1424650c1776976bcdfcb9841a3559b9986d3f30e20cd9e241e9d402230'::TEXT, ARRAY[1739]::BIGINT[]),
    (440::BIGINT, 'Si quiere pasar, es el indicado, pero si quiere aprender no. Lo recomiendo por que da material y si uno quiere aprender mas, el le ayuda, pero como tal da el curso por darlo'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'La participación importa']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '1b1d01c0241b2b2ec90d69f9041bced07c0ddb7b1330837e491af43ba074398d'::TEXT, ARRAY[1739]::BIGINT[]),
    (440::BIGINT, 'Si le toca como profesor asesor, retire el curso o apele la situación para cambiárselo. No ayuda en absolutamente nada, envía las retroalimentaciones fuera de tiempo y confusas, no responde mensajes ni correos a menos que vayan con copia a Biljhana, prácticamente es desarrollar un tfg solo'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-05-22T00:00:00+00:00'::TIMESTAMPTZ, 'e8da1b6a8f1cd156efe93f672a5cc23bcfe0a4ee7dd9eafef51e5251c4f1e1ca'::TEXT, ARRAY[2799]::BIGINT[]),
    (440::BIGINT, 'El mae es muy buena nota, pero MUY mal profe. A comparación de las otras profes del curso con este mae es demasiado fácil. Si quiere pasar el curso, matricule con él, pero tenga seguridad de no va a aprender absolutamente nada. El mae se pierde y se siente como que no sabe nada del tema.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas', 'Pocos exámenes']::TEXT[], '2023-12-02T00:00:00+00:00'::TIMESTAMPTZ, '8c5e2a15a8d2fc6d0ad6fdb16ba51dcd6b616ed0dab428c21bb7ebb3e61f2e37'::TEXT, ARRAY[1728]::BIGINT[]),
    (440::BIGINT, 'No importa el profe, el curso es muy teórico y un completo queque. Se aprende poco, deja muchas tareas pero sencillas y en grupo. Lo que más toma tiempo es el proyecto que no es teórico.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-28T00:00:00+00:00'::TIMESTAMPTZ, '3a791b58f24b900db934ec8773a818938451474c3399b4f3a835590736cdcb57'::TEXT, ARRAY[1749]::BIGINT[]),
    (440::BIGINT, 'El curso es importante, pero con él casi no se aprende, literal llega a leer presentaciones y hacer ejercicios resueltos. El curso se pasa sobrado porque las evaluaciones son sencillas y en grupos, califica suave.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-07-11T00:00:00+00:00'::TIMESTAMPTZ, 'ba4df4877229239973e5fa8e8921c30393cf2aa25c682fa3f2e61906de1e2bce'::TEXT, ARRAY[1778]::BIGINT[]),
    (440::BIGINT, 'Un mae super relajado no lo recomiendo porque no va a aprender ABSOLUTAMENTE nada. Y usted está para aprender no para el camino fácil, recomiendo matricular con el otro mae porque dicen que sí se aprende Literalmente este mae se pasa las clases por el trasero'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-08T00:00:00+00:00'::TIMESTAMPTZ, '31e20fef2065caf4a137601e8690921ed9b31985437b7170436c415e48f6da94'::TEXT, ARRAY[1739]::BIGINT[]),
    (440::BIGINT, 'Muy dejado, no se aprende casi nada. El curso es regalado'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2021-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'fdbd5858e482b9c932c4036055ededa71ac86ab931aba99d78ae2e2681524710'::TEXT, ARRAY[1749]::BIGINT[]),
    (440::BIGINT, 'Es un amor de profe legal, todo lo hace ver tan fácil y todo es muy fácil la verdad, no estresa y siempre busca la forma de ayudar al estudiante. Para quedarse con él hay que pulsearla legal. NO espere poder ver las evaluaciones hasta fin de semestre.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'b7c6404cbff537f0b319ea61a5b6a785b5ca361c60ed5a051a8cea6744a20a64'::TEXT, ARRAY[1739]::BIGINT[]),
    (440::BIGINT, 'El profe es un sol, súper amable, el curso en sí no es muy interesante, pero el profe trata de que uno aprenda y lo disfrute, no busca estresar al estudiante y le gusta que uno comparta su opinión del curso, las tareas y fechas de asignaciones, con el proyecto se aprende mucho y es sencillo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Pocos exámenes']::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'efe159e86546db4531e43e5c7c87bde146d2582e31025f800c738b237d70d053'::TEXT, ARRAY[1749]::BIGINT[]),
    (440::BIGINT, 'El profe más cosi de Produ, pero no se aprende nada, lee las presentaciones que son de la otra profe, tareas cortas y en grupo todas las semanas, revisa todo al final. Pero el curso en sí no es muy útil'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, 'ab508c71de2f0d15ce696b94e0be51f21db4ce71588f9d379a482ca7bfefcf98'::TEXT, ARRAY[1749]::BIGINT[]),
    (440::BIGINT, 'Pasar con el es suuuuumamente fácil Deja muchas tareas en grupo pero se hacen en menos de 10 minutos, y los exámenes igual'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'b244c509491509ea8e1e0ed417c4de99d7fdab2ee8b9d5728178d1314e7da4cd'::TEXT, ARRAY[1749]::BIGINT[]),
    (440::BIGINT, 'Bastante fácil pasar un curso con él, parece que no revisa los trabajos y pone notas al azar. No se aprende mucho y hay que buscar las cosas por cuenta propia, y clases muy lentas y largas. No responde correos'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '9cfbae6a81f5b040b0c241f36948e7b4b8f09033baf2957665fd4b5c0df95e59'::TEXT, ARRAY[1739]::BIGINT[]),
    (440::BIGINT, 'El profe es muy sencillo, pone a buscar bastantes cosas relacionadas en la materia, no se aprende mucho, pero es suuuuuper sencillo pasar los cursos con él.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2020-08-09T00:00:00+00:00'::TIMESTAMPTZ, '15d37ffe68ff804609a41f3e8ceb045cc9076d112e72ff62a99c19f1c9d79153'::TEXT, ARRAY[1749]::BIGINT[]),
    (440::BIGINT, 'El profe ayuda lo necesario, pero en ocasiones se pierde demasiado tiempo y se torna aburrido, especialmente en VS solo pone a copiar las progras y uno no sabe ni que está escribiendo'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, '60e6a58173716f2e46bdca2d133b7631797d3bf075f669540efa283a9ef741dd'::TEXT, ARRAY[1739]::BIGINT[]),
    (440::BIGINT, 'Casi no hace evaluaciones ni deja trabajos. Pone a copiar el código de la pizarra. Es muy aburrido y no se aprende nada. Todo lo que uno quiera aprender tiene que buscarlo por fuera. No responde correos, sí atiende dudas en persona pero ni siquiera sabe de que habla.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2019-11-25T00:00:00+00:00'::TIMESTAMPTZ, '068714941d8646ab686461e6a7af17d2cf24c081a7dc53dc9d9c62194e839089'::TEXT, ARRAY[1739]::BIGINT[]),
    (440::BIGINT, 'Se nota la falta de conocimiento a la hora de "enseñar " la materia. Como profesor es fácil, hace el curso nada pesado, pero tampoco va a aprender nada.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo']::TEXT[], '2019-11-02T00:00:00+00:00'::TIMESTAMPTZ, 'd1595fca08e5b1c72f6d8e3a3603794c71c4b979fb93b4766175c87e1c316782'::TEXT, ARRAY[1795]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
